import json, sys
from playwright.sync_api import sync_playwright
fx = json.load(open('/tmp/fixtures_v38.json')); gid = fx['gid']
errors = []; passed = 0; failed = 0
SHOTS = sys.argv[1] if len(sys.argv) > 1 else None
def ok(c, msg):
    global passed, failed
    if c: passed += 1; print('  ✓', msg)
    else: failed += 1; print('  ✗ FAIL:', msg)
def emit(page, ev, data): page.evaluate("([e,d]) => window.__srv.emit(e,d)", [ev, data])
def sent(page, name): return page.evaluate("(n) => (window.__sent||[]).filter(x => x[0]===n).map(x => x[1])", name)
def clear(page): page.evaluate("() => { window.__sent = []; }")
def shot(page, name):
    if SHOTS: page.screenshot(path=f'{SHOTS}/{name}.png')
def route_block(page):
    for pat in ('**/cdnjs.cloudflare.com/**', '**/flagcdn.com/**', '**/fonts.googleapis.com/**', '**/fonts.gstatic.com/**'): page.route(pat, lambda r: r.abort())
def watch(page, tag): page.on('pageerror', lambda e: errors.append(tag + ' PAGEERROR ' + str(e)))
LED = {'currency': 'USD', 'totalDeposited': 100020, 'moneyIn': 100020, 'moneyOut': 20, 'fees': 20, 'withdrawn': 0, 'inProgress': 0, 'held': 0, 'available': 100000, 'other': 0, 'reconciles': True, 'feeItems': []}
def acct(**o): return {**fx['verified'], 'countryIso': 'GH', 'balances': {'available': 100000, 'held': 0, 'pending': 0, 'totalDeposited': 100020}, 'ledger': LED, **o}
BILL = {'address1': '1600 Pennsylvania Avenue NW', 'address2': 'Suite 4', 'city': 'Washington', 'state': 'DC', 'zip': '20500', 'country': 'United States', 'countryIso': 'US'}
CARD = {'eligible': True, 'program': 'AIRWX', 'network': 'Visa', 'status': 'issued', 'fee': {'usd': 20, 'amount': 20, 'currency': 'USD', 'paid': True, 'ref': 'CF-1'}, 'balance': {'available': 100000, 'enough': True, 'short': 0}, 'verified': True, 'holder': 'Kwame Mensah',
        'card': {'last4': '1111', 'expMonth': 12, 'expYear': 2031, 'holder': 'KWAME MENSAH', 'issuedAt': '2026-10-22T10:00:00Z', 'frozen': False, 'frozenBy': None}}

def boot(b, a, w=390, h=800, extra=''):
    ctx = b.new_context(viewport={'width': w, 'height': h}); ctx.add_init_script("sessionStorage.setItem('q_splash_done','1'); localStorage.setItem('q_intro_done','1');" + extra)
    page = ctx.new_page(); watch(page, 'SELLER'); route_block(page)
    page.goto(f'http://localhost:8099/?groupId={gid}&role=SELLER', wait_until='load'); page.wait_for_timeout(600)
    emit(page, 'init-state', fx['init']); emit(page, 'seller-account-state', a); emit(page, 'receiving-details', fx['detailsUSD']); page.wait_for_timeout(250)
    page.evaluate("() => { const o = document.getElementById('onboardingOverlay'); if (o) o.remove(); openTxAccountView(); }"); page.wait_for_timeout(350)
    return ctx, page

with sync_playwright() as p:
    b = p.chromium.launch()

    print('\nA. Transfer is locked until the disbursement stage')
    ctx, page = boot(b, acct(disbursementEnabled=False, transfersOpen=False, manualSeller=False, pinSet=False))
    first = page.locator('#v41Home .v41-act').first
    ok(first.inner_text().strip() == 'Transfer' and 'Send' not in page.inner_text('.v41-actions'), '"Send" is now "Transfer" on Home')
    first.click(); page.wait_for_timeout(250)
    ok(page.is_visible('#wdBlockedModal') and 'Transfers are not open yet' in page.inner_text('#wdBlockedModal') and page.locator('#wdBlockedModal .v42-stages li').count() == 4, 'tapping it shows the disbursement-stage pop-up with the four stages')
    ok('Complete transaction' in page.inner_text('#wdBlockedActions') and page.is_visible('#txPageDashboard') and not page.is_visible('#txPageTransfer'), 'with a Complete transaction button; the form is not shown')
    shot(page, 'v42_locked_popup')
    page.evaluate("() => closeModal('wdBlockedModal')")
    page.click('#txBottomNav [data-bn=transfer]'); page.wait_for_timeout(250)
    ok(page.is_visible('#wdBlockedModal') and not page.is_visible('#txPageTransfer'), 'the Transfer tab shows the same pop-up and does not open the page')
    page.evaluate("() => closeModal('wdBlockedModal')")
    emit(page, 'disbursement-updated', {'groupId': gid, 'enabled': True}); page.wait_for_timeout(200)
    page.click('#txBottomNav [data-bn=transfer]'); page.wait_for_timeout(250)
    ok(page.is_visible('#txPageTransfer') and page.locator('#v42Transfer #v42tName').count() == 1, 'once the Desk moves it to disbursement, the Transfer page opens with its form')
    ctx.close()

    print('\nB. The Transfer page (admin-added seller: open at once)')
    ctx, page = boot(b, acct(disbursementEnabled=False, transfersOpen=True, manualSeller=True))
    page.locator('#v41Home .v41-act').first.click(); page.wait_for_timeout(300)
    ok(page.is_visible('#txPageTransfer') and not page.is_visible('#wdBlockedModal'), 'an admin-added seller goes straight to Transfer: no pop-up')
    t = page.inner_text('#v42Transfer')
    ok('Available to transfer' in t and '$100,000.00' in t and 'Local transfer' in t and 'International wire' in t and 'Account holder name' in t and 'Bank name' in t and 'Account number' in t and 'Bank country' in t and 'Amount to send' in t and 'Reference' in t, 'bank transfer form: type, recipient, bank details, country, amount, reference')
    ok('Send' not in page.inner_text('#txPageTransfer h1') and page.inner_text('#txPageTransfer h1').strip() == 'Transfer', 'the page title is Transfer')
    ok(page.evaluate("() => document.documentElement.scrollWidth <= innerWidth + 1"), 'no sideways scroll on a phone')
    shot(page, 'v42_transfer_phone')
    clear(page); page.click('#v42tGo'); ok(len(sent(page, 'request-withdrawal')) == 0 and 'holder' in page.inner_text('#v42tMsg').lower(), 'empty form: nothing sent, the first problem is explained')
    page.fill('#v42tName', 'John Smith'); page.fill('#v42tBank', 'HSBC'); page.fill('#v42tAcct', 'GB82 WEST 1234 5698 7654 33')
    page.click('#v42tGo'); ok('IBAN' in page.inner_text('#v42tMsg') and len(sent(page, 'request-withdrawal')) == 0, 'an IBAN with wrong check digits is refused')
    page.fill('#v42tAcct', 'GB82 WEST 1234 5698 7654 32'); page.click('#v42tGo'); ok('amount' in page.inner_text('#v42tMsg').lower() and 'Ghana' in page.inner_text('#v42tCountry'), 'a local transfer starts from the seller\'s own country (Ghana); the next missing item (the amount) is explained')
    page.click('#v42Transfer .v42-seg button:has-text("International")'); page.wait_for_timeout(150)
    ok(page.input_value('#v42tName') == 'John Smith' and 'SWIFT / BIC' in page.inner_text('#v42Transfer'), 'switching to International keeps what was typed and asks for SWIFT / BIC')
    page.click('#v42tCountry'); page.wait_for_timeout(250)
    page.evaluate("() => pickCountry('GB')"); page.wait_for_timeout(250)
    ok('United Kingdom' in page.inner_text('#v42tCountry'), 'the bank country is picked from the country list')
    page.fill('#v42tAmount', '250.50'); page.click('#v42tGo'); ok('SWIFT' in page.inner_text('#v42tMsg'), 'international: the SWIFT / BIC code is required')
    page.fill('#v42tSwift', 'hbukgb4b'); page.fill('#v42tAmount', '999999'); page.click('#v42tGo'); ok('more than your available' in page.inner_text('#v42tMsg'), 'an amount above the balance is refused')
    page.click('#v42Transfer .v42-amt button'); ok(page.input_value('#v42tAmount') == '100000.00', 'Max fills the available balance')
    page.fill('#v42tAmount', '250.50'); page.fill('#v42tRef', 'Invoice 2041')
    clear(page); page.click('#v42tGo'); s = sent(page, 'request-withdrawal')
    ok(len(s) == 1 and s[0]['kind'] == 'transfer' and s[0]['method'] == 'bank' and s[0]['beneficiaryName'] == 'John Smith' and s[0]['bankName'] == 'HSBC' and s[0]['bankAccount'] == 'GB82WEST12345698765432' and s[0]['bankSwift'] == 'HBUKGB4B' and s[0]['bankCountry'] == 'United Kingdom' and s[0]['reference'] == 'Invoice 2041' and s[0]['amount'] == 250.5 and s[0]['amountCurrency'] == 'USD' and s[0]['groupId'] == gid, 'a valid transfer is sent with every detail (IBAN tidied, SWIFT upper-case)')
    emit(page, 'withdrawal-code-sent', {'masked': 'k***@example.com', 'cooldownSec': 30, 'expiresInSec': 600}); page.wait_for_timeout(250)
    ok(page.is_visible('#wdCodeModal') and 'confirm this transfer' in page.inner_text('#wdCodeSub') and 'Invoice 2041' in page.inner_text('#wdCodeSummary'), 'the emailed-code box says "confirm this transfer" and shows the reference')
    emit(page, 'withdrawal-confirm-result', {'ok': True, 'id': 'x', 'ref': 'WD-AB12CD34'}); page.wait_for_timeout(250)
    ok('Transfer WD-AB12CD34 submitted' in page.inner_text('#toastContainer') and page.input_value('#v42tName') == '', 'on success: "Transfer … submitted" and the form is cleared')
    page.fill('#v42tName', 'Jane Roe'); emit(page, 'seller-account-state', acct(disbursementEnabled=False, transfersOpen=True, manualSeller=True)); page.wait_for_timeout(200)
    ok(page.input_value('#v42tName') == 'Jane Roe', 'a balance update while typing does not wipe the form')
    ctx.close()

    print('\nC. Crypto deposit stays reachable; incoming box keeps words inside')
    ctx, page = boot(b, acct(transfersOpen=True, manualSeller=True))
    long = [{'id': 'i1', 'ref': 'IN-7A1C33C7', 'payerName': 'VANNESSA INTERNATIONAL TRADING COMPANY LIMITED', 'purpose': 'x', 'amount': 100000, 'amountCurrency': 'USD', 'amountLedger': 100000, 'status': 'credited', 'receivedAt': '2026-10-22T09:00:00Z', 'feeAmount': 0, 'receivedInto': {'label': 'USD account ••8878'}},
            {'id': 'i2', 'ref': 'IN-9B2D44E8', 'payerName': 'Ama', 'purpose': 'y', 'amount': 1250.5, 'amountCurrency': 'USD', 'amountLedger': 1250.5, 'status': 'held_in_vault', 'receivedAt': '2026-10-23T09:00:00Z', 'feeAmount': 0, 'receivedInto': {'label': 'USD account ••8878'}}]
    emit(page, 'incoming-list', {'groupId': gid, 'incoming': long}); emit(page, 'receiving-details', fx['detailsUSD']); page.evaluate("() => setTxAccountNav('accounts')"); page.wait_for_timeout(400)
    ok(page.locator('#v42CryptoRow').count() == 1 and 'Deposit crypto' in page.inner_text('#v42CryptoRow'), 'Deposit crypto is on the Accounts page')
    clear(page); page.click('#v42CryptoRow .v41-item'); page.wait_for_timeout(200); ok(page.is_visible('#depositWizard'), 'and opens the crypto deposit wizard')
    page.evaluate("() => closeDepositWizard()")
    box = page.evaluate("""() => { const w = document.querySelector('#rcIncoming').getBoundingClientRect(); let worst = 999; const bad = [];
        document.querySelectorAll('#rcIncoming .rc-in b, #rcIncoming .rc-in small, #rcIncoming .rc-in span, #rcIncoming .rc-gt span').forEach((n) => { const r = n.getBoundingClientRect(); if (!r.width) return;
          const l = r.left - w.left, rt = w.right - r.right; worst = Math.min(worst, l, rt); if (n.scrollWidth > n.clientWidth + 1) bad.push('overflows: ' + n.textContent.trim().slice(0, 30)); if (l < 12 || rt < 12) bad.push(n.textContent.trim().slice(0, 30) + ' l=' + Math.round(l) + ' r=' + Math.round(rt)); });
        return { worst: Math.round(worst), bad }; }""")
    ok(not box['bad'], 'every word in the Incoming box stays at least 12px inside its edges (worst margin %spx) %s' % (box['worst'], box['bad']))
    shot(page, 'v42_incoming_phone')
    ctx.close()

    print('\nD. Card: no billing form; billing with the details; freeze')
    ctx, page = boot(b, acct(transfersOpen=True))
    page.click('#txBottomNav [data-bn=card]'); emit(page, 'my-card', CARD); page.wait_for_timeout(300)
    ok(page.locator('#txCardBody .v40-bill, #txCardBody .v40-billsum, #txCardBody .v40-editbill').count() == 0 and 'billing address appears' in page.inner_text('#txCardBody'), 'issued card: no billing form, and a line says it appears with the card details')
    ok(page.locator('#txCardBody .v42-freeze').count() == 1, 'a Freeze card button')
    clear(page); page.click('#txCardBody .v42-freeze'); ok(sent(page, 'set-card-frozen') == [{'groupId': gid, 'frozen': True}], 'Freeze sends the request')
    emit(page, 'my-card', {**CARD, 'status': 'frozen', 'card': {**CARD['card'], 'frozen': True, 'frozenBy': 'seller'}}); page.wait_for_timeout(250)
    ok('You froze this card' in page.inner_text('#txCardBody') and page.locator('#txCardBody button:has-text("Unfreeze card")').count() == 1 and 'contact Support' not in page.inner_text('#txCardBody'), 'frozen by the seller: Unfreeze card is offered')
    clear(page); page.click('#txCardBody button:has-text("Unfreeze card")'); ok(sent(page, 'set-card-frozen') == [{'groupId': gid, 'frozen': False}], 'Unfreeze sends the request')
    emit(page, 'my-card', {**CARD, 'status': 'frozen', 'card': {**CARD['card'], 'frozen': True, 'frozenBy': 'admin'}}); page.wait_for_timeout(250)
    ok('contact Support' in page.inner_text('#txCardBody') and page.locator('#txCardBody button:has-text("Unfreeze card")').count() == 0, 'frozen by the Desk: contact Support, no Unfreeze')
    emit(page, 'my-card', CARD); page.wait_for_timeout(150)
    emit(page, 'card-reveal', {'pan': '4111111111111111', 'expMonth': 12, 'expYear': 2031, 'cvv': '123', 'holder': 'KWAME MENSAH', 'billing': BILL, 'billingText': '...'}); page.wait_for_timeout(300)
    t = page.inner_text('#txCardBody')
    ok('4111 1111 1111 1111' in t and 'Billing address' in t and '1600 Pennsylvania Avenue NW' in t and 'Suite 4' in t and 'Washington' in t and 'DC' in t and '20500' in t and 'United States' in t, 'revealed details show the billing address: street, suite, city, state, ZIP, country')
    ok('ZIP code' in t and 'State' in t, 'US labels (State, ZIP code)')
    shot(page, 'v42_card_reveal_phone')
    page.click('#txCardBody button:has-text("Hide details")'); page.wait_for_timeout(200)
    ok('1600 Pennsylvania' not in page.inner_text('#txCardBody'), 'hiding the details hides the billing address too')
    ctx.close()

    print('\nE. App PIN: lock screen, prompts, setup')
    ctx, page = boot(b, acct(transfersOpen=True, pinSet=True))
    ok(page.is_visible('#v42Pin') and 'Enter your PIN' in page.inner_text('#v42Pin') and page.locator('#v42Pad button[data-k]').count() == 11, 'a PIN is set: the account opens behind a lock screen with a keypad')
    ok('Sign out' in page.inner_text('#v42PinOut') and page.evaluate("() => { const r = document.getElementById('v42Pin').getBoundingClientRect(); return r.width >= innerWidth && r.height >= innerHeight; }"), 'full screen, with Sign out and no way to cancel')
    shot(page, 'v42_pin_lock')
    clear(page)
    for d in '123450': page.click(f'#v42Pad [data-k="{d}"]')
    u = sent(page, 'unlock-pin'); ok(len(u) == 1 and u[0] == {'groupId': gid, 'pin': '123450'}, 'the sixth digit sends the PIN')
    emit(page, 'pin-result', {'ok': False, 'kind': 'unlock', 'left': 4, 'error': 'That PIN is not correct. 4 attempts left.'}); page.wait_for_timeout(150)
    ok('4 attempts left' in page.inner_text('#v42PinMsg') and page.locator('#v42Dots i.on').count() == 0 and page.is_visible('#v42Pin'), 'wrong PIN: message, dots cleared, still locked')
    clear(page); page.keyboard.type('482916'); ok(len(sent(page, 'unlock-pin')) == 1, 'the keyboard works too')
    emit(page, 'pin-result', {'ok': True, 'kind': 'unlock'}); page.wait_for_timeout(200)
    ok(not page.is_visible('#v42Pin') and page.is_visible('#txAccountView'), 'the right PIN opens the account')
    emit(page, 'seller-account-state', acct(transfersOpen=True, pinSet=True)); page.wait_for_timeout(200); ok(not page.is_visible('#v42Pin'), 'later updates do not lock it again')
    page.click('#txBottomNav [data-bn=card]'); emit(page, 'my-card', CARD); page.wait_for_timeout(200)
    emit(page, 'pin-required', {'action': 'reveal'}); page.wait_for_timeout(200)
    ok(page.is_visible('#v42Pin') and 'card details' in page.inner_text('#v42PinSub') and page.inner_text('#v42PinOut').strip() == 'Cancel', 'a sensitive action asks for the PIN again, with Cancel')
    clear(page); page.keyboard.type('482916'); emit(page, 'pin-result', {'ok': True, 'kind': 'unlock'}); page.wait_for_timeout(250)
    ok(sent(page, 'reveal-card') == [{'groupId': gid}] and not page.is_visible('#v42Pin'), 'after the PIN, the card details request is sent again automatically')
    emit(page, 'pin-required', {'action': 'unfreeze'}); page.wait_for_timeout(150); page.click('#v42PinOut'); ok(not page.is_visible('#v42Pin'), 'Cancel closes the prompt')
    page.evaluate("() => setTxAccountNav('security')"); page.wait_for_timeout(300)
    ok(page.locator('.v42-pincard').count() == 1 and 'App PIN' in page.inner_text('.v42-pincard') and 'on' in page.inner_text('.v42-pincard h3').lower() and page.locator('.v42-pincard button:has-text("Remove PIN")').count() == 1 and '2 minutes' in page.inner_text('.v42-pincard'), 'Security: the PIN card (On, change / remove, mentions the 2-minute sign-out)')
    shot(page, 'v42_security_pin')
    clear(page); page.click('#v42PinSave'); ok('password' in page.inner_text('#v42PinFormMsg').lower() and not sent(page, 'set-my-pin'), 'the account password is required')
    page.fill('#v42PinPw', 'Passw0rd!x'); page.fill('#v42PinNew', ''); page.type('#v42PinNew', '48a29167'); ok(page.input_value('#v42PinNew') == '482916', 'only digits are accepted, up to 6')
    page.fill('#v42PinNew2', '482917'); page.click('#v42PinSave'); ok('do not match' in page.inner_text('#v42PinFormMsg'), 'the two PINs must match')
    page.fill('#v42PinNew2', '482916'); clear(page); page.click('#v42PinSave'); ok(sent(page, 'set-my-pin') == [{'groupId': gid, 'pin': '482916', 'password': 'Passw0rd!x'}], 'a valid change is sent')
    emit(page, 'pin-result', {'ok': False, 'kind': 'set', 'error': 'That PIN is too easy to guess.', 'field': 'pin'}); page.wait_for_timeout(150); ok('too easy' in page.inner_text('#v42PinFormMsg'), 'a refusal from the server is shown')
    clear(page); page.click('.v42-pincard button:has-text("Remove PIN")'); ok(sent(page, 'remove-my-pin') == [{'groupId': gid, 'password': 'Passw0rd!x'}], 'Remove PIN sends the password')
    emit(page, 'pin-result', {'ok': True, 'kind': 'removed'}); page.wait_for_timeout(250); ok('off' in page.inner_text('.v42-pincard h3').lower() and page.locator('.v42-pincard button:has-text("Remove PIN")').count() == 0, 'after removing: PIN is Off')
    ctx.close()

    print('\nF. Sign out after 2 minutes without activity')
    ctx, page = boot(b, acct(transfersOpen=True, pinSet=False))
    ok(page.evaluate("() => window.__V42_IDLE_MS === undefined"), 'the real limit is 2 minutes (120 s)')
    src = page.evaluate("() => document.querySelector('script[src=\"/v42.js\"]') ? fetch('/v42.js').then(r => r.text()) : ''")
    ok('|| 120000' in src, 'the limit in the code is 120000 ms')
    page.evaluate("() => { window.__V42_IDLE_MS = 2500; sessionStorage.setItem('q_session_token', 'tok-old'); }"); clear(page)
    for _ in range(3): page.mouse.move(50, 50); page.wait_for_timeout(1200); page.mouse.move(80, 90)
    ok(page.is_visible('#txAccountView') and not sent(page, 'seller-logout'), 'while the person keeps using the app, nothing happens')
    page.wait_for_timeout(8500)
    ok(page.url.rstrip('/').endswith(':8099') and 'groupId' not in page.url, 'after the idle time the app is back at its start (signed out)')
    ok(page.evaluate("() => sessionStorage.getItem('q_session_token')") != 'tok-old', 'the old session token is gone')
    ok(page.locator('#v42Idle').count() == 1 and '2 minutes of inactivity' in page.inner_text('#v42Idle'), 'and a note says why: "signed out after 2 minutes of inactivity"')
    shot(page, 'v42_idle_note')
    ctx.close()
    print('\nG. The Desk Officer page is never signed out for being idle')
    o = b.new_context(viewport={'width': 1000, 'height': 700}); o.add_init_script("sessionStorage.setItem('q_splash_done','1')")
    op = o.new_page(); watch(op, 'OFFICER'); route_block(op); op.goto('http://localhost:8099/?officer=1', wait_until='load'); op.wait_for_timeout(500)
    op.evaluate("() => { window.__V42_IDLE_MS = 800; }"); op.wait_for_timeout(6500)
    ok(op.is_visible('#officerGate'), 'the officer sign-in page stays as it is')
    o.close()

    print('\nH. Everything quiet')
    ok(not errors, 'no JavaScript errors: ' + str(errors))
    b.close()
print(f'\nRESULT: {passed} passed, {failed} failed'); sys.exit(1 if failed else 0)
